def _get_masked_input(prompt=""):
    sys.stdout.write(prompt)
    sys.stdout.flush()
    password = ""
    if platform.system() == 'Windows':
        import msvcrt
        while True:
            ch = msvcrt.getwch()
            if ch in ('\r', '\n'):
                sys.stdout.write('\n')
                break
            elif ch == '\x03':
                raise KeyboardInterrupt
            elif ch == '\b':
                if len(password) > 0:
                    password = password[:-1]
                    sys.stdout.write('\b \b')
                    sys.stdout.flush()
            else:
                password += ch
                sys.stdout.write('*')
                sys.stdout.flush()
    else:
        import termios, tty
        fd = sys.stdin.fileno()
        old_settings = termios.tcgetattr(fd)
        try:
            tty.setraw(fd)
            while True:
                ch = sys.stdin.read(1)
                if ch in ('\n', '\r'):
                    sys.stdout.write('\n')
                    sys.stdout.flush()
                    break
                elif ch == '\x03':
                    raise KeyboardInterrupt
                elif ch in ('\x7f', '\b'):
                    if len(password) > 0:
                        password = password[:-1]
                        sys.stdout.write('\b \b')
                        sys.stdout.flush()
                else:
                    password += ch
                    sys.stdout.write('*')
                    sys.stdout.flush()
        finally:
            termios.tcsetattr(fd, termios.TCSADRAIN, old_settings)
    return password

